function makeExpandedConcept(ageBand: AgeBandV2, seed: ExpandedSeed, index: number): MelanieConcept {
  const [id, title, synopsis, genres, tones, themes, dynamics, settings, axes] = seed;
  const semanticSeed = EXPANDED_MELANIE_SEMANTIC_SEEDS[ageBand][id];
  if (!semanticSeed) throw new Error(`missing_expanded_melanie_semantic_fingerprint:${id}`);
  const [
    premiseFamily, centralActivities, settingClasses, protagonistRoles, narrativeEngine,
    relationshipShapes, speculativeDevices, stakesShapes, keyCoverMotifs, socialFocus,
  ] = semanticSeed;
  return {
    id,
    ageBand,
    title,
    synopsis,
    palette: PALETTES[index % PALETTES.length],
    attributes: {
      genres, tones, themes, dynamics, settings,
      speculation: axes[0] as MelanieAttributes["speculation"],
      darkness: axes[1] as MelanieAttributes["darkness"],
      humor: axes[2] as MelanieAttributes["humor"],
      romance: axes[3] as MelanieAttributes["romance"],
      mystery: axes[4] as MelanieAttributes["mystery"],
      scale: axes[5] as MelanieAttributes["scale"],
      emotion: axes[6] as MelanieAttributes["emotion"],
      pace: axes[7] as MelanieAttributes["pace"],
      character: axes[8] as MelanieAttributes["character"],
    },
    semantic: {
      premiseFamily,
      centralActivities: [...centralActivities] as MelanieSemanticFingerprint["centralActivities"],
      settingClasses: [...settingClasses] as MelanieSemanticFingerprint["settingClasses"],
      protagonistRoles: [...protagonistRoles] as MelanieSemanticFingerprint["protagonistRoles"],
      narrativeEngine,
      relationshipShapes: [...relationshipShapes] as MelanieSemanticFingerprint["relationshipShapes"],
      speculativeDevices: [...speculativeDevices] as MelanieSemanticFingerprint["speculativeDevices"],
      stakesShapes: [...stakesShapes] as MelanieSemanticFingerprint["stakesShapes"],
      keyCoverMotifs: [...keyCoverMotifs] as MelanieSemanticFingerprint["keyCoverMotifs"],
      socialFocus,
    },
  };
}

export const ADDITIONAL_MELANIE_CONCEPTS: Record<AgeBandV2, readonly MelanieConcept[]> = {
  kids: kidsSeeds.map((seed, index) => makeExpandedConcept("kids", seed, index)),
  preteens: preteensSeeds.map((seed, index) => makeExpandedConcept("preteens", seed, index)),
  teens: teensSeeds.map((seed, index) => makeExpandedConcept("teens", seed, index)),
  adult: adultSeeds.map((seed, index) => makeExpandedConcept("adult", seed, index)),
};
